BEGIN TRANSACTION READ ONLY; SET LOCAL search_path=pg_catalog; SET LOCAL statement_timeout='15s'; SET LOCAL lock_timeout='3s';
WITH targets(signature) AS (VALUES ('public.rpc_complete_worker_profile(uuid)'),('public.rpc_prepare_worker_ai_review_taxonomy(uuid,integer,boolean)'),('public.rpc_prepare_worker_ai_review_taxonomy_confirmed(uuid,integer,boolean,jsonb)'),('public.rpc_save_worker_ai_review(uuid,text,uuid)'),('public.rpc_submit_response(uuid,integer,uuid,integer,integer,timestamp with time zone,timestamp with time zone,text,text)'),('public.rpc_select_response(uuid,integer,uuid,integer,text,text)'),('private.worker_need_fit_v1(uuid,uuid,boolean)'))
SELECT jsonb_build_object('unit','R08_DEV_PREIMAGE','format_version',1,'captured_at',clock_timestamp(),'read_only',current_setting('transaction_read_only'),'server_version_num',current_setting('server_version_num')::int,'database',current_database(),'capture_role',current_user,
'functions',(SELECT jsonb_agg(jsonb_build_object('signature',t.signature,'oid',p.oid,'owner',pg_get_userbyid(p.proowner),'definition',pg_get_functiondef(p.oid),'definition_md5',md5(pg_get_functiondef(p.oid)),'security_definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl::text,'acl_entries',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY a.grantee,a.grantor,a.privilege_type,a.is_grantable),'[]'::jsonb) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))a)) ORDER BY t.signature) FROM targets t LEFT JOIN pg_proc p ON p.oid=to_regprocedure(t.signature)),
'new_helpers',(SELECT jsonb_object_agg(name,to_regprocedure(name) IS NOT NULL) FROM (VALUES('private.complete_worker_profile_v1(uuid,uuid,text)'),('private.worker_remote_review_ready_v1(jsonb)'),('private.worker_remote_only_activation_ready_v1(uuid,text[])')) n(name))) AS capture;
ROLLBACK;
